<template><section class="admin-page"><header class="admin-page__heading"><p class="admin-page__eyebrow">提效工具</p><h1>{{id?'编辑工具':'新建工具'}}</h1><p>当前状态：{{status}}</p></header><p v-if="loading">正在加载…</p>
<form v-else class="admin-card admin-form" @submit.prevent="save"><label>名称<input v-model="form.name" required></label><label>固定链接<input v-model="form.slug" pattern="[a-z0-9]+(?:-[a-z0-9]+)*"></label><label>摘要<textarea v-model="form.summary" required /></label><label>官方地址（HTTPS）<input v-model="form.officialUrl" type="url" pattern="https://.*" required></label><label>详细介绍</label><MarkdownEditor v-model="form.descriptionMarkdown"/><label>分类<select v-model="form.categoryId"><option :value="null">未分类</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><fieldset><legend>标签</legend><label v-for="t in tags" :key="t.id"><input v-model="form.tagIds" type="checkbox" :value="t.id">{{t.name}}</label></fieldset><label><input v-model="form.featured" type="checkbox">首页推荐</label><label>封面<input type="file" :accept="ACCEPTED_IMAGE_TYPES" @change="upload"></label><img v-if="coverUrl" :src="coverUrl" alt="工具封面预览"><p v-if="error" role="alert">{{error}}</p><p v-if="success" role="status">{{success}}</p><div><button v-if="status!=='ARCHIVED'" class="admin-button" :disabled="busy">保存草稿</button><button v-if="canPublish" type="button" :disabled="busy" @click="publish">保存并发布</button><button v-if="canArchive" type="button" :disabled="busy" @click="openDialog(archiveDialog)">归档</button><button v-if="id" type="button" :disabled="busy" @click="openDialog(deleteDialog)">删除</button></div></form>
<dialog ref="archiveDialog" aria-labelledby="tool-archive-title" aria-describedby="tool-archive-description"><h2 id="tool-archive-title">确认归档？</h2><p id="tool-archive-description">归档后工具将不再公开展示。</p><button @click="archive">确认归档</button><button @click="archiveDialog?.close()">取消</button></dialog><dialog ref="deleteDialog" aria-labelledby="tool-delete-title" aria-describedby="tool-delete-description"><h2 id="tool-delete-title">确认永久删除？</h2><p id="tool-delete-description">该操作无法撤销。</p><button @click="remove">确认删除</button><button @click="deleteDialog?.close()">取消</button></dialog></section></template>
<script setup lang="ts">
import{computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch}from'vue';import{onBeforeRouteLeave,useRoute,useRouter}from'vue-router';import type{CategoryResponse,TagResponse,ToolStatus,ToolWriteRequest}from'../../../shared/api/contracts';import{ApiProblem}from'../../../shared/api/problem';import{ACCEPTED_IMAGE_TYPES,uploadMedia}from'../../media/api';import MarkdownEditor from'../../articles/components/MarkdownEditor.vue';import{listCategories,listTags}from'../../topics/admin-api';import{archiveTool,createTool,loadAdminTool,publishTool,removeTool,updateTool}from'../admin-api'
const route=useRoute(),router=useRouter(),id=ref<number|null>(Number(route.params.id)||null),status=ref<ToolStatus>('DRAFT'),canPublish=computed(()=>status.value==='DRAFT'),canArchive=computed(()=>status.value==='PUBLISHED'),categories=ref<CategoryResponse[]>([]),tags=ref<TagResponse[]>([]),coverUrl=ref(''),error=ref(''),success=ref(''),busy=ref(false),loading=ref(true),ready=ref(false),dirty=ref(false),archiveDialog=ref<HTMLDialogElement>(),deleteDialog=ref<HTMLDialogElement>();const form=reactive<ToolWriteRequest>({name:'',slug:'',summary:'',descriptionMarkdown:'',officialUrl:'https://',coverMediaId:null,categoryId:null,tagIds:[],featured:false})
watch(form,()=>{if(ready.value)dirty.value=true},{deep:true});onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{const[c,t]=await Promise.all([listCategories(0,50,'TOOL'),listTags(0,50)]);categories.value=c.items;tags.value=t.items;if(id.value){const v=await loadAdminTool(id.value);Object.assign(form,{name:v.name,slug:v.slug,summary:v.summary,descriptionMarkdown:v.descriptionMarkdown,officialUrl:v.officialUrl,categoryId:v.category?.id??null,tagIds:v.tags.map(t=>t.id),featured:v.featured,coverMediaId:v.coverMediaId});coverUrl.value=v.coverUrl??'';status.value=v.status}}catch(e){fail(e,'工具加载失败')}finally{loading.value=false;ready.value=true}});onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));onBeforeRouteLeave(()=>dirty.value?window.confirm('有未保存的更改，确定离开吗？'):true)
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}function snapshot(){return JSON.stringify(form)}function copy():ToolWriteRequest{return JSON.parse(snapshot()) as ToolWriteRequest}function fail(e:unknown,message:string){error.value=e instanceof ApiProblem?(e.status===409&&/\bslug\b/i.test(e.detail)?'固定链接已存在，请更换。':e.detail):message}
async function persist(){const submitted=snapshot(),request=copy();busy.value=true;error.value='';success.value='';try{const creating=id.value===null,v=creating?await createTool(request):await updateTool(id.value!,request);id.value=v.id;status.value=v.status;const unchanged=snapshot()===submitted;if(unchanged)dirty.value=false;if(creating&&unchanged)await router.replace({name:'admin-tool-edit',params:{id:v.id}});success.value='草稿已保存';return true}catch(e){fail(e,'工具保存失败');return false}finally{busy.value=false}}async function save(){await persist()}async function publish(){if(!canPublish.value||!await persist()||!id.value)return;busy.value=true;try{const v=await publishTool(id.value);status.value=v.status;success.value='工具已发布'}catch(e){fail(e,'发布失败')}finally{busy.value=false}}async function archive(){if(!id.value||!canArchive.value)return;busy.value=true;try{const v=await archiveTool(id.value);status.value=v.status;success.value='工具已归档';archiveDialog.value?.close()}catch(e){fail(e,'归档失败')}finally{busy.value=false}}async function remove(){if(!id.value)return;busy.value=true;try{await removeTool(id.value);deleteDialog.value?.close();await router.push({name:'admin-tools'})}catch(e){fail(e,'删除失败')}finally{busy.value=false}}async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const m=await uploadMedia(f);form.coverMediaId=m.id;coverUrl.value=m.url}catch(e){fail(e,'封面上传失败')}}async function openDialog(dialog:HTMLDialogElement|undefined){if(typeof dialog?.showModal==='function')dialog.showModal();else dialog?.setAttribute('open','');await nextTick();dialog?.querySelector<HTMLButtonElement>('button')?.focus()}
</script><style scoped>img{max-width:420px;max-height:240px;object-fit:cover}</style>
